        if (value == null || value.isBlank()) {
            throw ApiException.badRequest("写操作必须携带全局唯一 X-Request-Id 请求头");
        }
        if (value.length() > MAX_ID_LENGTH) {
            throw ApiException.badRequest("X-Request-Id 长度不能超过 " + MAX_ID_LENGTH + " 个字符");
        }
        return value;
    }
}

