package com.example.starter.blind.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 盲态代码退役请求体；一次可退役多个处理代码，整批先校验后态再一次提交。
 *
 * @param reason 退役原因，必填非空，最长 500 字符，提交后不可变
 * @param codes  待退役处理代码集合（规范化为去重、排序后的 A/B 代码集合），不能为空；
 *               集合语义：重复元素视为异参冲突之外的请求非法（422），顺序不参与指纹
 */
public record RetireCodesRequest(
        @NotBlank(message = "reason 不能为空")
        @Size(max = 500, message = "reason 最长 500 字符")
        String reason,

        @NotEmpty(message = "codes 不能为空")
        List<@NotBlank(message = "codes 不能含空白代码") String> codes
) {
}

package com.example.starter.blind.dto;

/**
 * 退役批次中单个处理代码的不可变配额快照。
 * 数量单位均为“个序号（席位）”。
 *
 * @param treatment     被退役的处理代码 A/B
 * @param quotaBefore   退役前该代码总配额（席位数），要求值（设计值）
 * @param assignedCount 提交时刻已分配数量（含退组，席位不释放），实际值
 * @param sealedCount   本次封存的未分配序号数量，实际值（必然大于 0）
 * @param quotaAfter    退役后有效配额 = quotaBefore - assignedCount - 历次封存 - sealedCount，
 *                      被退役代码该值为 0
 */
public record RetiredCodeView(
        String treatment,
        int quotaBefore,
        int assignedCount,
        int sealedCount,
        int quotaAfter
) {
}

package com.example.starter.blind.dto;

/**
 * 退役批次的区组配额重算快照（不可变）。数量单位均为“个序号（席位）”。
 *
 * @param blockNo         区组号，从 1 开始
 * @param availableBefore 退役前区组可分配名额（未占用序号数；此前退役封存的序号不计入），实际值
 * @param sealedInBlock   本次退役在区组内封存的序号数，实际值
 * @param availableAfter  退役后区组可分配名额 = availableBefore - sealedInBlock，实际值
 * @param quotaAAfter     退役后区组内代码 A 的有效配额（未占用且未封存序号数），实际值
 * @param quotaBAfter     退役后区组内代码 B 的有效配额（未占用且未封存序号数），实际值
 */
public record BlockQuotaView(
        int blockNo,
        int availableBefore,
        int sealedInBlock,
        int availableAfter,
        int quotaAAfter,
        int quotaBAfter
) {
}

package com.example.starter.blind.dto;

/**
 * 封存序号明细视图；遵循盲态纪律，不返回席位号 seatNo 与处理代码 treatment，
 * 仅返回不透明条目编号、区组号与封存时间，区组号本身不暴露区组内位置。
 *
 * @param entryId      封存条目自增编号（不透明，无业务含义）
 * @param retirementId 封存该序号的退役批次编号
 * @param experimentId 实验编号
 * @param blockNo      被封存序号所在区组号
 * @param createdAt    封存时间，Unix 毫秒，UTC
 */
public record SealedSeatView(
        long entryId,
        String retirementId,
        String experimentId,
        int blockNo,
        long createdAt
) {
}

package com.example.starter.blind.dto;

/**
 * 处理代码诊断行（只读）；数量单位均为“个序号（席位）”。
 *
 * @param treatment     处理代码 A/B
 * @param quotaTotal    设计总配额（席位数），要求值
 * @param assignedCount 已分配数量（含退组），实际值
 * @param sealedCount   历次退役累计封存数量，实际值
 * @param availableQuota 剩余有效配额 = quotaTotal - assignedCount - sealedCount，实际值；
 *                       被退役代码为 0，新分配不得再使用该代码
 */
public record CodeQuotaView(
        String treatment,
        int quotaTotal,
        int assignedCount,
        int sealedCount,
        int availableQuota
) {
}

package com.example.starter.blind.dto;

import java.util.List;

/**
 * 实验退役/配额诊断视图（只读）：代码级配额与区组级当前可用名额，均为查询时刻实际值。
 *
 * @param experimentId 实验编号
 * @param codes        各处理代码配额诊断，按处理代码升序
 * @param blocks       各区组当前可用名额，按区组号升序
 */
public record RetirementDiagnosticsView(
        String experimentId,
        List<CodeQuotaView> codes,
        List<BlockQuotaView> blocks
) {
}

