                        + "THEN 1 ELSE 0 END) AS quota_a, "
                        + "SUM(CASE WHEN s.treatment = 'B' AND a.id IS NULL AND ss.id IS NULL "
                        + "THEN 1 ELSE 0 END) AS quota_b "
