        RetirementPlan plan = RetirementPlanner.plan(List.of("A"),
                seats(1, Set.of(), Set.of("1-3", "1-4")), 1);
        CodePlan codeA = plan.codes().get(0);
        assertEquals(2, codeA.sealedNow());
        BlockPlan block1 = plan.blocks().get(0);
        assertEquals(2, block1.availableBefore(), "已封存 B 序号不计入退役前可分配名额");
        assertEquals(2, block1.sealedInBlock());
        assertEquals(0, block1.availableAfter());
        assertEquals(0, block1.quotaAAfter());
        assertEquals(0, block1.quotaBAfter());
    }
}

