        ResponseEntity<String> reordered = rest.exchange(
                "/api/experiments/RC-3/code-retirements", HttpMethod.POST,
                new HttpEntity<>("{\"reason\":\"原因\",\"codes\":[\"B\",\"B\"]}",
                        headers("c1", "COORDINATOR", "rc3-key")), String.class);
