        JsonNode replayed = mapper.readTree(reordered.getBody());
        assertEquals(1, replayed.path("codes").size(), "回放的是首次快照，不重新执行");
        assertEquals("B", replayed.path("codes").get(0).path("treatment").asText());
    }

