    BlockPlan block1 = plan.blocks().get(0);
    assertEquals(1, block1.sealedInBlock());
    assertEquals(1, block1.availableBefore());
    assertEquals(0, block1.availableAfter(), "块1 自身名额归零，但全局仍有名额，允许");
    BlockPlan block2 = plan.blocks().get(1);
